// Private loopback integration only. All signer roles are generated by a NEW
// sandbox. No user keys, mainnet/testnet RPC, model, or old runtime are used.
import http from 'node:http';
import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {createRequire} from 'node:module';
import {randomUUID,randomBytes,createHash} from 'node:crypto';
import {createOnceDispatcher,refuseUnsignedReview} from './once-dispatcher.mjs';
import {readLocalState} from './read-model.mjs';
import {requireFinancialAdmission,isMaintenanceUnavailable} from './maintenance.mjs';
import {validatePublicActionInput} from './public-action-input.mjs';
import {positiveUnsignedRefusal,cacheOriginalObservation} from './pending-review.mjs';
import {createPolicyPreparer} from './policy-preparation.mjs';
import {fixture,ROOT,HERE as FINANCIAL,N,P,GAS} from '../financial-fork/v4-local-fixture.mjs';
import {assertRegistry,assertExistingBacking,ownerMandateQuote,gasAuthorization,withdrawalCostQuote} from '../financial-fork/v4-quote.mjs';
import {mandateId,policyHash} from '../financial-fork/v4-id.mjs';
import {assignmentPreview,PUBLIC_ACK,canonical} from '../financial-fork/assignment-client.mjs';
import {verifyDelivery,recipientPolicyHash,PROFILE} from '../delivery-envelope.mjs';
import {validateFinalOutcome} from '../../../../executor/outcome.mjs';
const require=createRequire(path.join(ROOT,'contract/package.json'));
const {transactions}=require('near-api-js'),{baseEncode,baseDecode}=require('@near-js/utils');
const HERE=fileURLToPath(new URL('./',import.meta.url));
const sha=x=>createHash('sha256').update(x).digest('hex');
const check=(v,m)=>{if(!v)throw Error(m);};
const exact=(v,keys)=>check(v&&typeof v==='object'&&!Array.isArray(v)&&Object.keys(v).sort().join(',')===keys.slice().sort().join(','),'Exact request fields required');
const pause=ms=>new Promise(r=>setTimeout(r,ms));
const methods={create:'create_mandate',post:'post_job',share:'publish_assignment',bid:'bid',award:'approve_award',claim:'claim',deliver:'deliver_encrypted',accept:'accept',pay:'withdraw_provider',close:'close_mandate',refund:'withdraw_owner'};
const roleFor={create:'owner',post:'operator',share:'owner',bid:'proofreader',award:'owner',claim:'proofreader',deliver:'proofreader',accept:'owner',pay:'proofreader',close:'owner',refund:'owner'};

export async function startLocalApp(){
 const f=await fixture('browser-owner-reviewer-v4-v2');let server,closed=false;
 try{
  for(const role of ['owner','operator','proofreader'])await f.activate(role);
  const accounts=Object.fromEntries(Object.keys(roleFor).map(a=>roleFor[a]).filter((x,i,a)=>a.indexOf(x)===i).map(r=>[r,f.actors[r].accountId]));
  const clientId='browser_harbor',mid=mandateId(accounts.owner,clientId),jid='proofread_0';
  const domain=canonical(f.pins),deadline=Date.now()+15*60*1000,cap=randomBytes(32).toString('hex');
  const plans=new Map(),publicRequests=new Map();let policy=null,dispatcher;
  const ownedRun=path.join(f.out,'app-originals');
  const elapsed=()=>Math.floor(Date.now()/1000);
  const intent=(role,method,args,deposit='0')=>({signer_id:accounts[role],receiver_id:f.registryId,method,args,gas:GAS.toString(),deposit});
  async function state(){return readLocalState({f,accounts,policy,mid,jid,clientId,now:elapsed,deriveDeliveryContext:deliveryContext});}
  async function mutationState(){const s=await state();requireFinancialAdmission(s.maintenance);assertRegistry(s.o,f.pins,elapsed());assertExistingBacking(s.o.registry.state);return s;}
  const discardedUnsigned=row=>positiveUnsignedRefusal(row.original_result,{request_id:row.request_id,intent_sha256:sha(canonical(row.intent))})&&row.original_result.review_reset_acknowledged===true;
  function requireReconciledReviews(){for(const row of publicRequests.values()){check(!row.inspection_conflict,'Original observation conflict requires inspection');check(row.status==='final'||discardedUnsigned(row),'Inspect or explicitly discard the exact original review before preparing another action');}}
  async function deliveryContext(m,j){const p=m.policy,r=p.recipient_policy;return {profile:PROFILE,chain_id:p.network.chain_id,genesis_hash:p.network.genesis_hash,registry_id:f.registryId,registry_code_hash:p.network.registry_code_hash,mandate_id:m.id,policy_sha256:m.policy_sha256,company_id:p.company_id,goal_id:p.goal_id,step_id:j.step_id,cycle:j.cycle,job_id:j.id,provider:j.provider,owner:m.owner,worker:p.operator,assignment_sha256:j.assignment_sha256,scope_sha256:j.scope_sha256,criteria_sha256:j.criteria_sha256,recipient_policy_sha256:await recipientPolicyHash(r),owner_key_id:r.owner.key_id,owner_key_version:r.owner.key_version,worker_key_id:r.worker.key_id,worker_key_version:r.worker.key_version};}
  const assignmentContext=(m,j)=>({chain_id:policy.network.chain_id,genesis_hash:policy.network.genesis_hash,registry_id:f.registryId,registry_code_hash:policy.network.registry_code_hash,mandate_id:m.id,policy_sha256:m.policy_sha256,company_id:policy.company_id,goal_id:policy.goal_id,step_id:j.step_id,cycle:j.cycle,job_id:j.id,owner:m.owner,scope_sha256:j.scope_sha256,criteria_sha256:j.criteria_sha256,bid_by:j.bid_by,delivery_seconds:policy.delivery_seconds,review_seconds:policy.review_seconds,expires_at:policy.expires_at});
  async function originalTransfer(kind){
   const matched=[...publicRequests.values()].filter(x=>x.action===(kind==='provider'?'pay':'refund')&&!discardedUnsigned(x));
   check(matched.length===0,'Existing original withdrawal must be inspected, never re-prepared');
   // This fact comes from this owned new run's sole durable dispatcher domain,
   // not from a caller-supplied "none" or a contract's missing transfer row.
   check((await fs.readdir(path.join(ownedRun,'requests'))).length===publicRequests.size,'Original request inventory incomplete');
   return {mandate_id:mid,status:'none'};
  }
  async function build(action,data,{existing=null}={}){
   check(Object.hasOwn(methods,action),'Unsupported local action');
   // This gate precedes state/RPC and all persistent dispatcher writes. Never
   // send private clear copy merely to discover a rejected contract response.
   await validatePublicActionInput(action,data,policy?.recipient_policy);
   const s=await mutationState(),{o,m,job}=s,role=roleFor[action];let args,deposit='0',quote;
   const mj={mandate_id:mid},jj={...mj,job_id:jid};
   if(action==='create'){
    check(!m&&policy,'A new original reviewed policy is required');
    const q=await f.view('quote_create_mandate',{owner:accounts.owner,client_id:clientId,policy},o.block_hash);o.create_quote={...q,block_hash:o.block_hash,height:o.height};
    const account=await f.provider.viewAccount(accounts.owner,{block_id:o.block_hash});check(account.block_hash===o.block_hash,'Same FINAL owner balance required');
    quote=ownerMandateQuote({observation:o,pins:f.pins,now:elapsed(),owner:accounts.owner,client_id:clientId,policy,expected_mandate_id:mid,expected_policy_sha256:policyHash(f.registryId,mid,accounts.owner,policy),gas:GAS.toString(),spendable_balance:account.amount});
    args={client_id:clientId,policy,approved_storage:q.storage,approved_budget:q.business_budget,public_metadata_ack:true};deposit=quote.attached_deposit;
   }else{
    check(m,'Create the reviewed mandate first');
    if(action==='post'){check(!job&&!m.closed,'Only the original next job may be posted');args={...mj,step_id:'proofread',cycle:0,policy_sha256:m.policy_sha256};}
    else{check(job,'Original job required');
     if(action==='share'){check(job.status==='open'&&!s.assignment&&job.bids.length===0,'Brief already committed or bidding has started');check(canonical(data.packet.context)===canonical(assignmentContext(m,job)),'Original brief context changed');check(canonical(await assignmentPreview({context:data.packet.context,source_evidence_sha256:data.packet.source_evidence_sha256,text:data.packet.text}))===canonical(data.packet),'Exact readable brief packet required');args={...jj,assignment:data.packet,public_share_ack:PUBLIC_ACK};}
     if(action==='bid'){check(job.status==='open'&&s.assignment&&job.bids.length===0,'Original readable brief and first bid required');args={...jj,assignment_sha256:job.assignment_sha256,scope_sha256:job.scope_sha256,price:P.toString(),terms_sha256:sha('LOCAL synthetic proofreading: original exact brief, no invented facts.')};}
     if(action==='award'){check(job.status==='open'&&job.bids.length===1&&job.bids[0].provider===accounts.proofreader,'Original allowlisted signed bid required');args={...jj,assignment_sha256:job.assignment_sha256,bid_sha256:job.bids[0].bid_sha256,policy_sha256:m.policy_sha256,dependency_sha256:sha(canonical([m.policy_sha256,job.assignment_sha256,job.scope_sha256,job.criteria_sha256]))};}
     if(action==='claim'){check(job.status==='awarded'&&job.provider===accounts.proofreader,'Original awarded reviewer required');args=jj;}
     if(action==='deliver'){check(job.status==='claimed'&&job.provider===accounts.proofreader&&!s.delivery,'Original claimed work required');await verifyDelivery(data.delivery,{expectedContext:{...await deliveryContext(m,job),content_sha256:data.delivery.context.content_sha256},recipientPolicy:policy.recipient_policy});args={...jj,delivery:data.delivery};}
     if(action==='accept'){check(job.status==='delivered'&&s.delivery,'Original delivered work required');args={...jj,assignment_sha256:job.assignment_sha256,delivery_sha256:job.delivery_sha256};}
     if(action==='pay'||action==='refund'){
      const kind=action==='pay'?'provider':'owner';check(action==='pay'?job.status==='accepted':m.closed,'Original accepted credit or closed owner record required');
      if(existing){
       const own=publicRequests.get(existing);check(own&&own.action===action&&own.request_id===existing,'Original withdrawal request inventory required');
       check([...publicRequests.values()].filter(x=>x.action===action&&!discardedUnsigned(x)).every(x=>x.request_id===existing),'Another original withdrawal exists; inspect it');
       o.original_intent={mandate_id:mid,status:'none'};
      }else o.original_intent=await originalTransfer(kind);
      const w=await f.view('quote_withdrawal',{...mj,kind,...(kind==='provider'?{job_id:jid}:{})},o.block_hash);o.withdrawal_quote={...w,block_hash:o.block_hash,height:o.height};
      const account=await f.provider.viewAccount(accounts[role],{block_id:o.block_hash});check(account.block_hash===o.block_hash,'Same FINAL original recipient balance required');
      quote=withdrawalCostQuote({observation:o,pins:{...f.pins,mandate_id:mid,policy_sha256:m.policy_sha256},now:elapsed(),mandate:m,job,kind,transfer_id:kind==='provider'?'provider_browser':'owner_browser',gas:GAS.toString(),spendable_balance:account.amount});args=quote.args;deposit=quote.attached_deposit;
     }
     if(action==='close'){check(job.status==='paid'&&!m.closed,'Pay original reviewer before closing this demo budget');args=mj;}
    }
   }
   check(args,'Action unavailable');
   const tx=intent(role,methods[action],args,deposit),gas=gasAuthorization({observation:o,pins:f.pins,now:elapsed(),actions:[{type:'FunctionCall',method:tx.method,args:tx.args,gas:tx.gas}]});
   return {s,role,intent:tx,costs:{attached_deposit:deposit,network_gas_authorization:gas.total_authorization,project_code_charge:'0',provider_payment:action==='create'?policy.lifetime:action==='award'?P.toString():'0',storage_collateral:quote?.record_storage_collateral??quote?.new_record_storage_collateral??'0'},quote,observed_at_ms:Date.now()};
  }
  const ports={
   authorize:async(request)=>{
    const plan=plans.get(request.request_id);check(plan&&canonical(request.intent)===canonical(plan.intent)&&request.role===plan.role,'Exact original public review required');
    if(Date.now()>plan.expires_at_ms)refuseUnsignedReview('review_expired');
    let fresh;try{fresh=await build(plan.action,plan.data,{existing:request.request_id});}catch(error){if(isMaintenanceUnavailable(error))refuseUnsignedReview('maintenance');throw error;}
    check(canonical(fresh.intent)===canonical(plan.intent)&&BigInt(fresh.costs.network_gas_authorization)<=BigInt(plan.costs.network_gas_authorization),'Reviewed original intent or gas cap changed; prepare a fresh review before signing');
    if(Date.now()>plan.expires_at_ms)refuseUnsignedReview('review_expired');
    return {domain,intent_sha256:request.intent_sha256,observed_at_ms:Date.now(),expires_at_ms:Math.min(Date.now()+30000,plan.expires_at_ms)};
   },
   sign:async(tx)=>{
    check(tx.receiver_id===f.registryId&&Object.values(accounts).includes(tx.signer_id),'Only new isolated fixture signers may sign');
    const c=f.sandbox.worker.manager.connection,key=await c.signer.getPublicKey(tx.signer_id,c.networkId),head=(await f.provider.block({finality:'final'})).header;
    const access=await f.provider.query({request_type:'view_access_key',account_id:tx.signer_id,public_key:key.toString(),block_id:head.hash});check(access.permission==='FullAccess','Original local access key changed');
    const nonce=BigInt(access.nonce)+1n,[h,signed]=await transactions.signTransaction(tx.receiver_id,nonce,[transactions.functionCall(tx.method,Buffer.from(JSON.stringify(tx.args)),BigInt(tx.gas),BigInt(tx.deposit))],baseDecode(head.hash),c.signer,tx.signer_id,c.networkId);
    return {hash:baseEncode(h),wire_base64:Buffer.from(transactions.encodeTransaction(signed)).toString('base64'),nonce:nonce.toString(),public_key:key.toString(),recent_block_hash:head.hash};
   },
   broadcastOnce:async(wire,hash)=>{
    check(/^http:\/\/127\.0\.0\.1:[0-9]+$/.test(f.sandbox.rpcAddr),'Only owned loopback chain allowed');
    // fetch has no application retry. An uncertain response is inspect-only.
    const response=await fetch(f.sandbox.rpcAddr,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:'original-'+hash,method:'send_tx',params:{signed_tx_base64:wire,wait_until:'NONE'}}),signal:AbortSignal.timeout(12000)});
    check(response.ok,'Original broadcast transport uncertain');const data=await response.json();check(!data.error,'Original broadcast outcome uncertain');
    const ack=typeof data.result==='string'?data.result:data.result?.transaction?.hash;check(!ack||ack===hash,'Original broadcast hash mismatch');
   },
   observeOriginal:async({hash,signer_id})=>{for(let i=0;i<35;i++){try{const raw=await f.provider.txStatus(hash,signer_id,'FINAL');if(raw.final_execution_status==='FINAL')return raw;}catch(e){if(!/UNKNOWN_TRANSACTION|not found|does not exist|doesn't exist|not started/i.test(e.message))throw e;}await pause(200);}return null;},
   validateFinal:async(raw,{hash,intent:tx})=>{
    const checked=validateFinalOutcome(raw,{hash,method:tx.method,id:tx.args.job_id??null},tx.signer_id,tx.receiver_id),actions=raw.transaction.actions;
    check(Array.isArray(actions)&&actions.length===1&&actions[0].FunctionCall,'Original one-call transaction required');const a=actions[0].FunctionCall;
    check(a.method_name===tx.method&&String(a.gas)===tx.gas&&a.deposit===tx.deposit&&Buffer.from(a.args,'base64').toString('utf8')===JSON.stringify(tx.args),'Original signed arguments, gas or deposit differ');
    return checked;
   }
  };
  dispatcher=await createOnceDispatcher({directory:ownedRun,domain,accounts,deadline,ports});
  async function safeState(){const {o,m,job,assignment,delivery,maintenance}=await state();return {maintenance,environment:'ACTUAL_ISOLATED_LOCAL_NEAR',company_is_fictional:true,real_human_hire:false,model_calls:0,accounts,pins:f.pins,deadline,client_id:clientId,mandate_id:mid,job_id:jid,policy,m,job,assignment,delivery,assignment_context:job?assignmentContext(m,job):null,delivery_context:job?.provider?await deliveryContext(m,job):null,final:{hash:o.block_hash,height:o.height,observed_at:o.observed_at},requests:[...publicRequests.values()].map(x=>({request_id:x.request_id,action:x.action,status:x.status,inspection_conflict:x.inspection_conflict===true,...x.original_result})),project_quote:f.projectQuote};}
  async function complete(request_id){
   const row=publicRequests.get(request_id);check(row,'Original browser request missing');const result=await dispatcher.inspect(request_id);
   const next=Object.fromEntries(Object.entries(result).filter(([k,v])=>v!==undefined&&['status','request_id','hash','checked','intent_sha256','new_signature','no_retry','review_reset_allowed','review_reset_acknowledged','reason'].includes(k)));
   cacheOriginalObservation(row,next,{request_id,intent_sha256:sha(canonical(row.intent))});
   if(result.status==='final'&&result.checked.status==='final'&&['pay','refund'].includes(row.action)){
    const recipient=accounts[row.action==='pay'?'proofreader':'owner'],rows=await f.principalTransfers(result.raw,recipient);check(rows.length===1,'Exact original native principal receipt required');
    const actions=rows[0].receipt.receipt.Action.actions;check(actions.length===1&&actions[0].Transfer.deposit===row.intent.args.approved_amount,'Exact native payment amount required');
    row.original_result.principal={recipient,amount:row.intent.args.approved_amount,receipt_id:rows[0].outcome.id};
    try{await f.artifact('APP-PRINCIPAL-'+request_id+'.json',rows);}catch(e){if(e.code!=='EEXIST')throw e;}
   }
   return structuredClone(row.original_result);
  }
  const prepareLocalPolicy=createPolicyPreparer({validatePublic:recipientPolicyHash,getPrepared:()=>policy,readAdmission:mutationState,buildProposal:async recipientPolicy=>{
     const proposed=await f.policy('owner',{recipient_policy:recipientPolicy,max_cycles:1,max_open:1,bid_seconds:3600,delivery_seconds:1200,review_seconds:600});
     // Validate public key shapes and actual RSA4096 before retaining metadata.
     const o=await f.observe(),q=await f.view('quote_create_mandate',{owner:accounts.owner,client_id:clientId,policy:proposed},o.block_hash);o.create_quote={...q,block_hash:o.block_hash,height:o.height};
     ownerMandateQuote({observation:o,pins:f.pins,now:elapsed(),owner:accounts.owner,client_id:clientId,policy:proposed,expected_mandate_id:mid,expected_policy_sha256:policyHash(f.registryId,mid,accounts.owner,proposed),gas:GAS.toString(),spendable_balance:(await f.actors.owner.availableBalance()).toString()});return proposed;
  },commit:proposed=>{policy=structuredClone(proposed);}});
  const staticFiles=new Map([['/',['index.html','text/html']],['/app.css',['app.css','text/css']],['/app.mjs',['app.mjs','text/javascript']],['/pending-review.mjs',['pending-review.mjs','text/javascript']],['/policy-preparation.mjs',['policy-preparation.mjs','text/javascript']],['/delivery-envelope.mjs',[path.resolve(HERE,'../delivery-envelope.mjs'),'text/javascript']],['/modules/assignment-client.mjs',[path.resolve(FINANCIAL,'assignment-client.mjs'),'text/javascript']],['/web-chain/src/crypto.js',[path.resolve(ROOT,'web-chain/src/crypto.js'),'text/javascript']]]);
  let origin;
  async function body(req){check(req.headers['content-type']==='application/json','JSON required');let n=0,b=[];for await(const c of req){n+=c.length;check(n<=110000,'Bounded public request required');b.push(c);}return JSON.parse(Buffer.concat(b).toString('utf8'));}
  server=http.createServer(async(req,res)=>{
   res.setHeader('Cache-Control','no-store');res.setHeader('X-Content-Type-Options','nosniff');res.setHeader('Referrer-Policy','no-referrer');res.setHeader('Content-Security-Policy',"default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'");
   const json=(value,status=200)=>{res.writeHead(status,{'content-type':'application/json'});res.end(JSON.stringify(value));};
   try{
    check(req.headers.host===new URL(origin).host,'Owned loopback host required');check(!req.headers.origin||req.headers.origin===origin,'Foreign origin refused');check(!req.headers['sec-fetch-site']||['same-origin','none'].includes(req.headers['sec-fetch-site']),'Foreign browser surface refused');
    const u=new URL(req.url,origin);check(!u.search&&!u.hash,'No arbitrary request query');
    if(req.method==='GET'&&staticFiles.has(u.pathname)){const [file,type]=staticFiles.get(u.pathname);res.writeHead(200,{'content-type':type});res.end(await fs.readFile(path.isAbsolute(file)?file:path.join(HERE,file)));return;}
    if(req.method==='GET'&&u.pathname==='/api/hello'){json({cap,accounts,pins:f.pins,deadline,run_id:path.basename(f.out)});return;}
    check(req.headers['x-bin-local-capability']===cap,'Current local page capability required');
    if(req.method==='GET'&&u.pathname==='/api/state'){json(await safeState());return;}
    check(req.method==='POST'&&req.headers.origin===origin,'Explicit local page action required');
    const b=await body(req);
    if(u.pathname==='/api/policy'){
     exact(b,['recipient_policy']);json(await prepareLocalPolicy(b.recipient_policy));return;
    }
    if(u.pathname==='/api/prepare'){
     exact(b,['action','data']);requireReconciledReviews();const fresh=await build(b.action,b.data),request_id=randomUUID(),plan={request_id,action:b.action,data:structuredClone(b.data),role:fresh.role,intent:fresh.intent,costs:fresh.costs,expires_at_ms:Date.now()+45000};plans.set(request_id,plan);
     json({...plan,data:undefined,final_block:fresh.s.o.block_hash});return;
    }
    if(u.pathname==='/api/approve'){
     exact(b,['request_id','reviewed_intent_sha256']);const plan=plans.get(b.request_id);check(plan&&sha(canonical(plan.intent))===b.reviewed_intent_sha256,'Exact reviewed action required');
     const prior=publicRequests.get(b.request_id);
     if(prior){json(await complete(b.request_id));return;}
     publicRequests.set(b.request_id,{request_id:b.request_id,action:plan.action,intent:plan.intent,status:'preparing'});
     try{const result=await dispatcher.send({request_id:b.request_id,role:plan.role,intent:plan.intent});json(await complete(b.request_id));}
     catch(e){publicRequests.get(b.request_id).status='inspect_original';throw e;}return;
    }
    if(u.pathname==='/api/reset-review'){
     exact(b,['request_id','reviewed_intent_sha256']);check(publicRequests.has(b.request_id),'Original browser review required');
     await dispatcher.discardUnsignedReview(b.request_id,b.reviewed_intent_sha256);json(await complete(b.request_id));return;
    }
    if(u.pathname==='/api/inspect'){exact(b,['request_id']);json(await complete(b.request_id));return;}
    throw Error('Unsupported explicit local route');
   }catch(e){json({error:e.message,no_automatic_retry:true},400);}
  });
  await new Promise(r=>server.listen(0,'127.0.0.1',r));origin='http://127.0.0.1:'+server.address().port;
  await f.artifact('LOCAL-APP-READY.json',{origin,run_id:path.basename(f.out),pins:f.pins,accounts,deadline,app_signature_cap:32,setup_transactions:f.records.length,no_public_deployment:true,no_model:true,no_user_keys:true});
  await f.stage('local-browser-ready',{origin,deadline});
  const stop=async()=>{if(closed)return;closed=true;await new Promise(r=>server.close(r));await f.close();};
  process.once('SIGINT',()=>stop().then(()=>process.exit(0)));process.once('SIGTERM',()=>stop().then(()=>process.exit(0)));
  // Closing the finite server is not a runtime restart or a nonce reset. The
  // complete original request files remain for separately reviewed recovery.
  const timer=setTimeout(()=>stop(),15*60*1000);timer.unref();
  return {origin,out:f.out,stop,server};
 }catch(e){if(server)server.close();await f.close();throw e;}
}
if(process.argv[1]&&pathToFileURL(path.resolve(process.argv[1])).href===import.meta.url){const app=await startLocalApp();console.log(JSON.stringify({local_app_url:app.origin,run_directory:app.out,finite_minutes:15}));}
